// Package store keeps logged-in sessions and sweeps out idle ones.
package store

import (
	"context"
	"time"
)

// Session is a logged-in session.
type Session struct {
	ID       string
	LastSeen time.Time
}

// SweepEvery is how often the sweeper runs.
const SweepEvery = 5 * time.Minute

// Store holds the sessions and the clock they are stamped with.
type Store struct {
	Sessions *Repo[string, Session]
	Now      func() time.Time
}

// New is an empty store on the wall clock.
func New() *Store {
	return &Store{Sessions: NewRepo[string, Session](), Now: time.Now}
}

// Sweep removes sessions idle for more than an hour.
func (s *Store) Sweep() {
	now := s.Now()
	for _, ses := range s.Sessions.All() {
		if now.Sub(ses.LastSeen) > time.Hour {
			s.Sessions.Delete(ses.ID)
		}
	}
}

// RunSweeper sweeps every SweepEvery until ctx is done.
func (s *Store) RunSweeper(ctx context.Context) {
	t := time.NewTicker(SweepEvery)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			s.Sweep()
		}
	}
}

// Touch records activity on a session at the current time.
func (s *Store) Touch(id string) {
	s.Sessions.Put(id, Session{ID: id, LastSeen: s.Now()})
}

package store

import (
	"maps"
	"slices"
	"sync"
)

// Repo is an in-process key-value store, safe for concurrent use.
type Repo[K comparable, V any] struct {
	mu sync.Mutex
	m  map[K]V
}

// NewRepo is an empty store.
func NewRepo[K comparable, V any]() *Repo[K, V] {
	return &Repo[K, V]{m: map[K]V{}}
}

// Get is the value stored at k, and whether there is one.
func (r *Repo[K, V]) Get(k K) (V, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	v, ok := r.m[k]
	return v, ok
}

// Put stores v at k.
func (r *Repo[K, V]) Put(k K, v V) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.m[k] = v
}

// Delete removes k.
func (r *Repo[K, V]) Delete(k K) {
	r.mu.Lock()
	defer r.mu.Unlock()
	delete(r.m, k)
}

// All is every stored value, in no particular order.
func (r *Repo[K, V]) All() []V {
	r.mu.Lock()
	defer r.mu.Unlock()
	return slices.Collect(maps.Values(r.m))
}

package store

import (
	"testing"
	"time"
)

type fakeClock struct{ t time.Time }

func (c *fakeClock) now() time.Time          { return c.t }
func (c *fakeClock) advance(d time.Duration) { c.t = c.t.Add(d) }

// newFake is an empty store on a fake clock.
func newFake() (*Store, *fakeClock) {
	c := &fakeClock{time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)}
	s := New()
	s.Now = c.now
	return s, c
}

func TestASweepRemovesOnlySessionsIdleForMoreThanAnHour(t *testing.T) {
	s, clock := newFake()
	s.Touch("old")
	clock.advance(50 * time.Minute)
	s.Touch("fresh")
	clock.advance(20 * time.Minute)
	s.Sweep()
	if _, ok := s.Sessions.Get("old"); ok {
		t.Error("old session survived the sweep")
	}
	if _, ok := s.Sessions.Get("fresh"); !ok {
		t.Error("fresh session was swept")
	}
}

func TestAdvancingTheClockAloneNeverSweeps(t *testing.T) {
	s, clock := newFake()
	s.Touch("old")
	clock.advance(2 * time.Hour)
	if _, ok := s.Sessions.Get("old"); !ok {
		t.Error("session removed without a sweep")
	}
}
